// LED plugged directly into D13 and its neighboring GND header.
const int LED_PIN = 13;
void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  digitalWrite(LED_PIN, HIGH);
  Serial.println(1);
  delay(500);
  digitalWrite(LED_PIN, LOW);
  Serial.println(0);
  delay(500);
}

